contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 extra) public payable {
        require(extra > 0);
        uint256 beforeBalance = address(c).balance;
        require(beforeBalance <= type(uint256).max - extra);
        uint256 amount = beforeBalance + extra;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && address(c).balance == beforeBalance);
    }

    receive() external payable {}
}

