// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 extra) internal {
        vm.assume(extra > 0);
        uint256 beforeBalance = address(c).balance;
        vm.assume(beforeBalance <= type(uint256).max - extra);
        uint256 amount = beforeBalance + extra;
        bool reverted;
        try c.withdraw(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && address(c).balance == beforeBalance);
    }

    function testFuzz_run(uint256 extra) public {
        _run(extra);
    }

    receive() external payable {}
}
